describe('Public Profile Page - Shared Information Display', () => {
  beforeEach(() => {
    cy.visit('/user/profile');
  });

  it('should display public profile page with shared information when logged in', () => {
    // Setup: Login as a user
    cy.get('[data-testid="login-button"]').click();
    cy.get('[data-testid="email-input"]').type('user@example.com');
    cy.get('[data-testid="password-input"]').type('password123');
    cy.get('[data-testid="login-button"]').click();

    // Verify login success
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="user-name"]').should('contain', 'User');

    // Verify public profile page is visible
    cy.get('[data-testid="profile-header"]').should('be.visible');
    cy.get('[data-testid="profile-name"]').should('contain', 'User');

    // Verify shared information is displayed
    cy.get('[data-testid="profile-bio"]').should('be.visible');
    cy.get('[data-testid="profile-bio"]').should('contain', 'Cypress QA automation engineer');

    cy.get('[data-testid="profile-location"]').should('be.visible');
    cy.get('[data-testid="profile-location"]').should('contain', 'New York');

    cy.get('[data-testid="profile-avatar"]').should('be.visible');
    cy.get('[data-testid="profile-avatar"]').should('have.attr', 'src');

    // Verify social media links are present
    cy.get('[data-testid="profile-social-links"]').should('be.visible');
    cy.get('[data-testid="profile-linkedin-icon"]').should('be.visible');
    cy.get('[data-testid="profile-linkedin-icon"]').should('have.attr', 'href');

    // Verify contact information is displayed
    cy.get('[data-testid="profile-email"]').should('be.visible');
    cy.get('[data-testid="profile-email"]').should('contain', 'user@example.com');

    // Verify profile settings are visible
    cy.get('[data-testid="profile-settings-button"]').should('be.visible');

    // Verify footer is present
    cy.get('[data-testid="profile-footer"]').should('be.visible');

    // Verify no error messages are displayed
    cy.get('[data-testid="error-message"]').should('not.exist');

    // Verify page title
    cy.get('[data-testid="page-title"]').should('contain', 'User Profile');

    // Verify navigation links are visible
    cy.get('[data-testid="profile-nav-links"]').should('be.visible');

    // Verify profile page is fully loaded
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });

  it('should display error message when user is not logged in', () => {
    // Setup: Attempt to access profile page without logging in
    cy.visit('/user/profile');

    // Verify error message is displayed
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please log in to view your profile');

    // Verify login button is still visible
    cy.get('[data-testid="login-button"]').should('be.visible');

    // Verify profile header is not visible
    cy.get('[data-testid="profile-header"]').should('not.exist');

    // Verify no shared information is displayed
    cy.get('[data-testid="profile-bio"]').should('not.exist');

    // Verify no social media links are visible
    cy.get('[data-testid="profile-social-links"]').should('not.exist');

    // Verify no contact information is displayed
    cy.get('[data-testid="profile-email"]').should('not.exist');

    // Verify profile settings are not visible
    cy.get('[data-testid="profile-settings-button"]').should('not.exist');

    // Verify page title is still present
    cy.get('[data-testid="page-title"]').should('contain', 'User Profile');

    // Verify navigation links are still visible
    cy.get('[data-testid="profile-nav-links"]').should('be.visible');

    // Verify page is still fully loaded
    cy.get('[data-testid="loading-spinner"]').should('not.exist');
  });
});
